SELECT DATE_FORMAT(m.created_at, '%Y-%m-%d %H:00') AS hour_utc, COUNT(*) AS n, SUM(m.delivery_status='APPLIED') AS applied, SUM(m.delivery_status<>'APPLIED') AS not_applied, ROUND(AVG(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at))/1000) AS avg_lag_ms, ROUND(MAX(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at))/1000) AS max_lag_ms, SUM(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at) > 2000000) AS n_gt_2s, SUM(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at) > 10000000) AS n_gt_10s FROM crypto_ai.market_price_event m WHERE m.source='BINANCE_KLINE_DIRECT_FIX153' AND m.delivery_status IN ('APPLIED','NON_CANONICAL','PROTECTION_NOT_APPLIED','PENDING') AND m.created_at BETWEEN '2026-10-11 20:50:00' AND '2026-10-12 10:10:00' GROUP BY hour_utc ORDER BY hour_utc LIMIT 20